          "Dân số: Người Lự có 6.757 người theo Điều tra 53 dân tộc thiểu số ngày 1/4/2019. Cộng đồng cư trú tập trung ở tỉnh Lai Châu, trong đó có các huyện Phong Thổ, Sìn Hồ; một bộ phận sinh sống tại khu vực Điện Biên.",
          "Hoạt động sản xuất: Ruộng nước là nguồn sinh kế quan trọng. Người Lự tạo hệ thống mương, phai để đưa nước từ suối vào ruộng; lúa nếp được gieo mạ rồi cấy theo hai lần. Tại một số nơi, người dân sử dụng phân xanh, rác hữu cơ và phân chuồng để bón ruộng. Ngoài trồng lúa, họ làm nương bằng cách phát cây, đốt thực bì, chọc lỗ tra hạt; kỹ thuật dùng cày được tiếp thu qua giao lưu với người Mông ở địa phương. Nghề dệt thổ cẩm phát triển trong gia đình, tạo ra vải dùng may áo, váy, khăn và chăn. Săn bắt, hái lượm và đánh cá suối cũng từng góp phần bổ sung thức ăn; nghề rèn gươm được nhắc đến như một nghề thủ công nổi tiếng của người Lự."
