          "Nhà mới và lễ tết: Khi làm nhà mới, gia đình tránh tổ chức lễ lên nhà vào giữa trưa. Nghi thức truyền thống có sự tham gia của các cụ cao tuổi ngoài họ, vợ chồng chủ nhà và những người phụ nữ trẻ mang đuốc lên nhóm bếp. Ngọn lửa trong nhà mới được giữ liên tục trong ba ngày ba đêm; sau lễ cúng tổ tiên, dân bản cùng ăn uống, hát theo tiếng sáo đôi. Người Lự cũng có các nghi lễ cúng tổ tiên, cúng bản và cúng rừng thiêng theo từng thời điểm trong năm, gắn với mong muốn bản làng bình yên và mùa màng thuận lợi."
