          "Nhà mới: Lễ dựng nhà có nghi thức nhóm lửa ở bếp. Gia chủ làm hình cá bằng bẹ chuối, buộc lên cột bếp và đặt quả bí xanh ở cột cái; trước khi nấu ăn, gia đình làm lễ xin thần bếp đặt ba hòn đầu rau và hòn đá cái. Trong đêm đầu tiên, ngọn lửa được giữ cháy, họ hàng và hàng xóm cùng uống rượu cần, chúc mừng gia chủ. Những chi tiết này là tập quán ở một số địa phương, không còn phổ biến trong mọi lễ lên nhà hiện nay.",
