          "Gia đình và hôn nhân: Quan hệ gia đình và dòng họ có vị trí quan trọng trong xã hội truyền thống. Hôn nhân được thực hiện thông qua nhiều nghi thức, từ tìm hiểu, ăn hỏi đến cưới. Sau khi kết hôn, trong truyền thống từng tồn tại hình thức cư trú bên nhà vợ trong một thời gian trước khi vợ chồng có thể chuyển sang sống bên nhà chồng hoặc tổ chức nơi ở riêng. Điều này cho thấy xã hội Rơ Măm từng có những dấu vết của quan hệ mẫu hệ, mặc dù về sau chịu nhiều biến đổi.",
