// Helper normalize string for searching
export function normalizeName(str = '') {
  return str
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLocaleLowerCase('vi')
    .replace(/[’']/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

// Map alias names to canonical slugs
const SLUG_BY_ALIAS = {
  'viet': 'kinh',
  'hmong': 'hmong',
  'h mong': 'hmong',
  'mong': 'hmong',
  'meo': 'hmong',
  'kho ho': 'co-ho',
  'k ho': 'co-ho',
  'cor': 'co',
  'khor': 'co',
  'ca dong': 'co',
  'raglay': 'ra-glai',
  'raglai': 'ra-glai',
  'khmer nam bo': 'khmer',
  'cham nam bo': 'cham',
  'pa co': 'ta-oi',
  'van kieu': 'bru-van-kieu',
  'bru van kieu': 'bru-van-kieu',
  'cao lan': 'san-chay',
  'san chi': 'san-chay',
  'san chay cao lan va san chi': 'san-chay',
  'chau ro': 'cho-ro',
  'do ro': 'cho-ro',
  'x tieng': 'xtieng',
  'stieng': 'xtieng'
};

// Fast lookup helper by slug, name or alias
export function getEthnicDetails(query = '') {
  if (!query) return null;
  const rawQuery = String(query).trim();
  if (ETHNIC_DETAILS[rawQuery]) {
    return ETHNIC_DETAILS[rawQuery];
  }

  const norm = normalizeName(rawQuery);
  const aliasSlug = SLUG_BY_ALIAS[norm];
  if (aliasSlug && ETHNIC_DETAILS[aliasSlug]) {
    return ETHNIC_DETAILS[aliasSlug];
  }

  // Search by exact or partial name
  for (const [slug, item] of Object.entries(ETHNIC_DETAILS)) {
    if (normalizeName(item.name) === norm || normalizeName(item.slug) === norm) {
      return item;
    }
  }

  for (const [slug, item] of Object.entries(ETHNIC_DETAILS)) {
    if (normalizeName(item.name).includes(norm) || norm.includes(normalizeName(item.name))) {
      return item;
    }
  }

  return null;
}
